// === ANPASSEN an deine Notion-Tabelle ===
// Deine Notion-Datenbank-ID (32 Hex-Zeichen aus der DB-URL).
const DB_ID = "{{REPLACE_ME_NOTION_DB_ID}}";
// Map: Vorname (lowercase) -> Notion-User-ID. User-IDs via Notion-API GET /v1/users.
// Leer lassen ist ok, dann greift immer DEFAULT_OWNER.
const OWNER_MAP = {
  // "vorname": "{{REPLACE_ME_NOTION_USER_ID}}",
};
// Fallback-Owner, wenn kein Name passt (z.B. du selbst).
const DEFAULT_OWNER = "{{REPLACE_ME_DEFAULT_OWNER_USER_ID}}";
// HINWEIS: Die Property-Namen unten ("Activity Title", "Status", ...) muessen
// EXAKT den Spalten deiner Tabelle entsprechen. Passe sie an.
const norm = $('Normalize Input').first().json;
let raw = (($('Extract Tasks').first().json.output) ?? '').toString().trim();
raw = raw.replace(/^```(json)?/i, '').replace(/```$/,'').trim();
let tasks = [];
try { tasks = JSON.parse(raw); } catch (e) { tasks = []; }
if (!Array.isArray(tasks)) tasks = [];
const pageId = (norm.notion_page_id ?? '').toString().trim();
const validRel = /^[0-9a-fA-F]{32}$/.test(pageId.replace(/-/g,''));
const items = [];
for (const t of tasks) {
  const title = (t.title ?? '').toString().trim();
  if (!title) continue;
  const ownerKey = (t.owner ?? '').toString().trim().toLowerCase();
  const ownerId = OWNER_MAP[ownerKey] || DEFAULT_OWNER;
  const priority = ['High','Medium','Low'].includes(t.priority) ? t.priority : 'Medium';
  const detail = (t.detail ?? '').toString().trim();
  const due = (t.due_date ?? '').toString().trim();
  const validDue = /^\d{4}-\d{2}-\d{2}$/.test(due);
  const props = {
    "Activity Title": { title: [{ text: { content: title } }] },
    "Status": { status: { name: "Not started" } },
    "Priority": { select: { name: priority } },
    "Owner": { people: [{ id: ownerId }] }
  };
  if (detail) props["Action Items"] = { rich_text: [{ text: { content: detail } }] };
  if (validDue) props["Due Date"] = { date: { start: due } };
  if (validRel) props["Meeting"] = { relation: [{ id: pageId }] };
  items.push({ json: {
    requestBody: { parent: { database_id: DB_ID }, properties: props },
    title, owner_id: ownerId, priority, due_date: validDue ? due : "",
    meeting_id: norm.meeting_id, run_id: norm.run_id
  }});
}
return items;
